signals.provider_specific_streaming:
import { lumic } from "@adaptic/lumic-utils";

export async function ask(prompt: string): Promise<string> {
  const response = await lumic.llm.call<{ events: { type: string; text: string }[] }>(
    prompt,
    "text",
    { model: "claude-haiku-4-5", stream: true },
  );
  let text = "";
  for (const event of response.data.events) {
    if (event.type === "content_block_delta") {
      text += event.text;
    }
  }
  return text;
}
